// El input en n8n puede venir como texto o como objeto, aseguramos el parseo
let inputData = $input.first().json.output.response;

// Si la respuesta viene dentro de una propiedad de texto (por ejemplo, en un .data o .body), extráela. 
// Si el JSON completo ya es el elemento de entrada, usa directamente:
let rawString = typeof inputData === 'string' ? inputData : JSON.stringify(inputData);

// Limpiamos los saltos de línea de control si es necesario y parseamos a objeto limpio
let limpio = JSON.parse(rawString.replace(/[\r\n]+/g, " "));

return { json: limpio };
